import pdfplumber
import pandas as pd
import json

def clean_val(val, field):
    if val is None:
        return val
    if field in ['Salary', 'Years', 'Score']:
        if isinstance(val, str):
            val = val.replace(',', '')
        try:
            if field == 'Score':
                return float(val)
            else:
                return int(float(val))
        except (ValueError, TypeError):
            return val
    return str(val).strip()

def extract_pdf_data(file_path):
    all_data = []
    with pdfplumber.open(file_path) as pdf:
        for i, page in enumerate(pdf.pages):
            table = page.extract_table()
            if table:
                start_row = 0
                # Check if first row is header
                if i == 0 and table[0][0] == 'ID':
                    start_row = 1
                elif table[0][0] == 'ID': # Some PDFs repeat header
                    start_row = 1

                for row in table[start_row:]:
                    if not row or not row[0]: continue
                    all_data.append(row)

    columns = ['ID', 'First', 'Last', 'Dept', 'Position', 'Salary', 'Years', 'Location', 'Score']
    df = pd.DataFrame(all_data, columns=columns)

    for col in columns:
        df[col] = df.apply(lambda r: clean_val(r[col], col), axis=1)

    return df

def main():
    pdf_df = extract_pdf_data('/root/employees_backup.pdf')
    xlsx_df = pd.read_excel('/root/employees_current.xlsx')

    # Ensure xlsx data is cleaned similarly
    columns = ['ID', 'First', 'Last', 'Dept', 'Position', 'Salary', 'Years', 'Location', 'Score']
    for col in columns:
        xlsx_df[col] = xlsx_df.apply(lambda r: clean_val(r[col], col), axis=1)

    pdf_dict = pdf_df.set_index('ID').to_dict('index')
    xlsx_dict = xlsx_df.set_index('ID').to_dict('index')

    deleted_employees = []
    modified_employees = []

    # Identify deleted employees
    for emp_id in pdf_dict:
        if emp_id not in xlsx_dict:
            deleted_employees.append(emp_id)

    # Identify modified employees
    for emp_id, old_data in pdf_dict.items():
        if emp_id in xlsx_dict:
            new_data = xlsx_dict[emp_id]
            for field in columns[1:]: # Skip ID
                old_val = old_data[field]
                new_val = new_data[field]
                if old_val != new_val:
                    modified_employees.append({
                        "id": emp_id,
                        "field": field,
                        "old_value": old_val,
                        "new_value": new_val
                    })

    deleted_employees.sort()
    modified_employees.sort(key=lambda x: (x['id'], x['field']))

    report = {
        "deleted_employees": deleted_employees,
        "modified_employees": modified_employees
    }

    with open('/root/diff_report.json', 'w') as f:
        json.dump(report, f, indent=2)

if __name__ == "__main__":
    main()

